CREATE TABLE IF NOT EXISTS passport_usernames (user_id BIGINT NOT NULL PRIMARY KEY, username VARCHAR(12) NOT NULL UNIQUE, created_at BIGINT NOT NULL, CONSTRAINT passport_usernames_user_fk FOREIGN KEY (user_id) REFERENCES passport_users(user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS passport_user_email_otps (id VARCHAR(64) NOT NULL PRIMARY KEY, user_id BIGINT NOT NULL, email VARCHAR(320) NOT NULL, code_hash TEXT NOT NULL, attempt_count INT NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL DEFAULT 'pending', expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, INDEX passport_user_email_otps_lookup (user_id, status, created_at), CONSTRAINT passport_user_email_otps_user_fk FOREIGN KEY (user_id) REFERENCES passport_users(user_id) ON DELETE CASCADE);
